<template>  <header class="nav_wrap">    <div class="header_wrap">      <div class="header_content" :class="isCheck ? 'banner_white' : 'banner_transparent'">        <div class="grid_content" :class="{isLogin:showMenu}">          <h1 class="header_logo">            <router-link to="/">              <img v-if="!isCheck" src="@/assets/images/icon_logo_white.svg" alt="logo">              <img v-else src="@/assets/images/icon_logo.svg" alt="logo">            </router-link>          </h1>          <div class="group_menu_wrap" v-if="!showMenu">            <nav id="gnb_skip" class="gnb_wrap" tabindex="0">              <ul class="gnb_1depth">                <li v-for="i in submenus" :key="i.id">                  <a href="javascript:void(0);" @click.prevent="handleNextScreen(i.screenName)">{{ i.name }}</a>                </li>              </ul>            </nav>            <label class="burger" for="burger">              <input id="burger" v-model="hiddenMenu" type="checkbox"/>              <span/>              <span/>              <span/>            </label>            <button v-if="userInfo" class="btn_logout" @click="handleLogout"><span>로그아웃</span></button>          </div>        </div>      </div>      <div class="gnb_submenu_horizontal" :class="{ on: hiddenMenu }" @mouseenter="handleHoverDepth1(true)"          @mouseleave="handleHoverDepth1(false)">        <div v-for="submenu in submenus" id="sub2" class="gnb_2depth" :key="submenu.id">          <div class="grid_content">            <strong class="gnb_tit">{{ submenu.name }}</strong>            <ul>              <li v-for="submenuDep2 in submenu.subMenus" :key="submenuDep2.di">                <a href="javascript:void(0);"                    @click.prevent="handleNextScreen(submenuDep2.screenName)">{{ submenuDep2.name }}</a>                <ul class="gnb_3depth">                  <li v-for="submenuDep3 in submenuDep2.subMenus" :key="submenuDep3.id">                    <a href="javascript:void(0);"                        @click.prevent="handleNextScreen(submenuDep3.screenName)">{{ submenuDep3.name }}</a>                  </li>                </ul>              </li>            </ul>          </div>        </div>      </div>    </div>    <div class="header_wrap_mobile" :class="{ on: hiddenMenu }">      <div class="header_container">        <div class="lnb_submenu_horizontal">          <div v-for="(submenu,index) in submenus" id="sub2" class="lnb_depth" :key="submenu.id">            <div class="grid_content">              <input :id="`lnb_menu_${index}`" type="checkbox" class="lnb_checkbox"/>              <label :for="`lnb_menu_${index}`" class="lnb_tit">{{ submenu.name }}</label>              <ul class="lnb_1depth">                <li v-for="submenuDep2 in submenu.subMenus" :key="submenuDep2.id">                  <a href="javascript:void(0);"                      @click.prevent="handleNextScreen(submenuDep2.screenName)">{{ submenuDep2.name }}</a>                  <ul class="lnb_2depth">                    <li v-for="submenuDep3 in submenuDep2.subMenus" :key="submenuDep3.id">                      <a href="javascript:void(0);"                          @click.prevent="handleNextScreen(submenuDep3.screenName)">{{ submenuDep3.name }}</a>                    </li>                  </ul>                </li>              </ul>            </div>          </div>        </div>      </div>    </div>  </header></template><script lang="ts" setup>import {computed, onMounted, ref, toRef} from "vue";import globalCommon from '@/utils/global'import {commonStore} from "@/stores/common";import {useRouter} from "vue-router";import {SCREEN} from "@/router/screen";import {useFetchData} from "@/utils/useFetchData";import {PostType} from "@/stores/common/demoFetchData/demo.type";import {END_POINTS_HEADER_MENU} from "@/stores/common/commonServices/commonServices.service";import commonService from "@/service/common/CommonService";import {SUCCSESS_STATUS} from "@/constants/screen.const";import {getUserInfo} from "@/utils/storage";const router = useRouter()const store = commonStore()const hiddenMenu = ref(false);// const hiddenMenu = ref(true);const activeLnbMenu = ref(0)const submenus = ref(null)const showMenu = toRef(store, "isShowMenu")const showBackground = toRef(store, "isShowBackground")const userInfo = getUserInfo()onMounted(() => {  getData()})watch(() => showMenu.value, (value) => {  getData()})const getData = async () => {  if (!userInfo) {    return  }  const {    dataFetch,    statusFetch,    error,    isLoading,    fetchData  } = await useFetchData<PostType[]>(`${END_POINTS_HEADER_MENU}`, {    method: "POST"  });  if (statusFetch.value === SUCCSESS_STATUS) {    submenus.value = dataFetch.value.data  }}const handleHoverDepth1 = (value: boolean) => {  hiddenMenu.value = value;};const isCheck = computed(() => {  //Add conditions if needed, (for example only show on dashboard)  // return (isScroll.value || hiddenMenu.value || containerClass.value !== 'large') && !props.showMenu  return (isScroll.value || hiddenMenu.value || containerClass.value !== 'large') || !showBackground.value})const {windowWidth, containerClass} = globalCommon.useResponsive()const {isScroll} = globalCommon.useScroll(1)const handleLogout = async () => {  await commonService.logout();  await router.push({name: SCREEN.login.name})}type ScreenNameType = keyof typeof SCREEN;const handleNextScreen = (screenName: ScreenNameType) => {  if (screenName && SCREEN[screenName] && SCREEN[screenName].name) {    return router.push({name: SCREEN[screenName].name});  }};</script>